files.dedupe.py:
def unique(items):
    """Removes duplicates from a list."""
    return sorted(set(items))

files.tests/test_dedupe.py:
from dedupe import unique


def test_removes_duplicates():
    assert unique([1, 1, 2]) == [1, 2]


def test_empty():
    assert unique([]) == []


def test_unique_keeps_first_seen_order():
    assert unique([1, 2, 3]) == [1, 2, 3]


def test_unique_with_key_function():
    assert unique(["a", "b"]) == ["a", "b"]


def test_unique_keeps_first_of_each_duplicate():
    assert unique([1, 1]) == [1]

